import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
ini={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_020_independent_answers.json').read_text())['questions']}
items=[]
def add(q,stem,values,reasons,ans,solution,core,concept,labels,cites,conditions=None,ambiguity='',discipline='apt_2',law=False,table=False,direction='適切な組合せ',verdicts=None):
 r=by[q];assert len(values)==len(reasons)==5
 if verdicts is None:verdicts=['整合する' if i==ans else '整合しない' for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions or {'方向':direction},choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='問題幹・全5肢・否定・文字・数値・時点を原典画像で照合。'+('ア等の順序と組合せ表の全セルを別々に確認。' if table else '設問固有図なし。'),ambiguity=ambiguity,evidence=ini[q]['source_images_viewed'],core_concept=core,required_knowledge=core+'。'+solution,solution=solution,independent_answer=ini[q]['independent_answer'],independent_solution_note='S7_020_independent_answers.jsonに公式正答参照前の判断を保存。'+ini[q]['reason']+' 後続の一次資料確認による条件追記・誤植発見は初回を上書きしない。',answer_reason=solution,learning_points='活動・物質・制度の対象と評価の境界を固定し、用語の入替、全部/一部、法的義務/目標、出題時/現在を区別する。'+core+'を個別の技術活動に結び付ける。',theory_references=['theory:environment:'+s for s in labels] if discipline=='apt_2' else ['theory:safety:preparedness'],discipline_id=discipline,concept_id=concept,classification_reason='原典全肢から中心課題を確定。'+core+'を主概念にし、環境という広い旧自動語彙や誤った工程管理タグを修正する。',calculation='false',figure=str(table).lower(),law=str(law).lower(),evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='0',figure_reading='1' if table else '0',difficulty='2',difficulty_reason='専門外の制度・概念の境界を知った上で、個々の真偽と候補対応を二段階で比較する。疑義や特殊正答は難易度と別にAstra対象として保持。'),citations=cites,foundationality='high',transferability='high'))
def combo(q,stem,statements,truth,rows,ans,core,concept,labels,cites,ambiguity='',law=False):
 names='アイウエオカキ'[:len(truth)];assert len(statements)==len(truth)
 conditions={'方向':'個々の記述の○/×に適合する組合せ。','並び':'・'.join(names)}
 for n,(v,w),t in zip(names,statements,truth):conditions[n]=v+' 判定'+('○' if t=='O' else '×')+'：'+w
 vals=['・'.join('○' if t=='O' else '×' for t in row) for row in rows]
 reasons=[]
 for row in rows:
  bad=[names[i] for i,(a,b) in enumerate(zip(row,truth)) if a!=b]
  reasons.append('個別判断の'+vals[ans-1]+'と全項目で一致する。' if not bad else '個別判断と異なるのは'+ '・'.join(bad)+'である。各記述の理由は確認条件欄に示す。')
 solution=' '.join(n+'は'+('○' if t=='O' else '×')+'。'+w for n,(_,w),t in zip(names,statements,truth))+' よって'+vals[ans-1]+'の候補'+str(ans)+'を選ぶ。'
 add(q,stem,vals,reasons,ans,solution,core,concept,labels,cites,conditions,ambiguity,law=law,table=True)
